import { queryPersonCount } from '@/api/xcnanr/statisticalAnalysis';
import xtTreeLzaySelect from '@/components/xtTreeLzaySelect/index.vue';
import { getAll } from '@/api/xcnanr/authorizedPerson';
export default {
  name: 'index',
  components: {
    xtTreeLzaySelect: xtTreeLzaySelect
  },
  data: function data() {
    return {
      workTimes: [],
      operatorOptions: [],
      searchForm: {
        pageNumber: 1,
        pageSize: 10,
        startDate: undefined,
        endDate: undefined,
        companyId: undefined,
        workerId: undefined
      },
      total: 0,
      tableData: [],
      tableHeight: undefined,
      tableLoading: false,
      repairStatusList: [],
      auth: ''
    };
  },
  created: function created() {
    this.getOperatorOptions();
  },
  mounted: function mounted() {
    this.initSearchForm();
    this.$nextTick(function () {
      // this.setTableHeight()
    });
    this.setPageContentHeight();
    this.getList();
  },
  methods: {
    /**
     * 被授权人员下拉
     */
    getOperatorOptions: function getOperatorOptions() {
      var _this = this;
      getAll({
        enabled: 1
      }).then(function (res) {
        _this.operatorOptions = res.data;
      });
    },
    /**
     * 查询
     */
    queryEvent: function queryEvent() {
      this.searchForm.pageNumber = 1;
      this.searchForm.pageSize = 10;
      this.getList();
    },
    /**
     * 重置
     */
    resetEvent: function resetEvent() {
      this.initSearchForm();
      this.getList();
    },
    initSearchForm: function initSearchForm() {
      this.searchForm = {
        pageNumber: 1,
        pageSize: 10,
        startDate: undefined,
        endDate: undefined,
        companyId: undefined,
        workerId: undefined
      };
    },
    getCompanyItem: function getCompanyItem(val) {
      this.searchForm.companyId = val.id;
      this.searchForm.companyName = val.fullName;
      this.$forceUpdate();
    },
    /**
     * 获取表格数据
     */
    getList: function getList() {
      var _this2 = this;
      this.tableLoading = true;
      this.tableLoading = true;
      // 给查询时间段赋值
      if (this.searchForm.workTimes && this.searchForm.workTimes.length > 0) {
        this.searchForm.startDate = this.searchForm.workTimes[0] + ' 00:00:00';
        this.searchForm.endDate = this.searchForm.workTimes[1] + ' 23:59:59';
      } else {
        this.searchForm.startDate = null;
        this.searchForm.endDate = null;
      }
      queryPersonCount(this.searchForm).then(function (res) {
        _this2.tableData = res.data.records;
        _this2.total = res.data.total;
        _this2.tableLoading = false;
      }).catch(function () {
        _this2.tableLoading = false;
      });
    },
    // 设置表格高度
    setTableHeight: function setTableHeight() {
      var bodyBox = document.getElementsByClassName('page_body');
      this.tableHeight = bodyBox[0].offsetHeight - 50 + 'px';
    },
    selectionChange: function selectionChange(selection) {
      this.selectionList = selection.map(function (item) {
        return item.id;
      });
    }
  }
};
